#!/bin/bash
# AES-AUDIT-001 — VLM visual critiques (harsh principal-designer persona) for remaining surfaces.
cd /home/z/my-project/download/aes-audit-001/shots
set -u

PERSONA="أنت مصمم منتجات أول (Principal Product Designer) قاسٍ بلا رحمة، تحكم على واجهات SaaS احترافية. الواجهة عربية RTL داكنة لنظام هندسة وكيلية (Agentic Engineering System)."

z-ai vision -p "$PERSONA هذه شاشة محادثة حقيقية على 1440px (لقطة viewport ثم لقطة صفحة كاملة). انقد بكسلاً بكسلاً: 1) بنية الرسائل: تمييز رسالة المستخدم عن ردود المساعد، الترويسات، الحشو، المحاذاة 2) عمود المحادثة وعرضه 3) صندوق الإدخال وشريط أدواته 4) الشريط الجانبي وقائمة الجلسات 5) اتساق الألوان والطباعة 6) درجة /10 مع أخطر 3 عيوب حرفية. كن قاسياً ومحدداً." -i "./02-conversation-1440.png" -i "./02-conversation-1440-full.png" -o vlm-02-conversation.json 2>&1 | tail -1

z-ai vision -p "$PERSONA هذه «غرفة تحكم مصنع الوكلاء» (Factory Control Room) على 1440px (viewport ثم كاملة). انقدها: 1) هيكل اللوحة: هل تبدو كغرفة تحكم حقيقية أم جدول بيانات؟ 2) كثافة المعلومات مقابل الوضوح 3) البلاطات الإحصائية وأرقامها (حجم خط الأرقام mono؟) 4) الجداول والصفوف 5) التسلسل الهرمي بين المهمة/الأدوار/الأحداث 6) الألوان الدلالية للحالات 7) درجة /10 وأخطر 3 عيوب حرفية قابلة للقياس." -i "./03-factory-1440.png" -i "./03-factory-1440-full.png" -o vlm-03-factory.json 2>&1 | tail -1

z-ai vision -p "$PERSONA هاتان لقطتان لدرج الإعدادات: تبويب «الأدوات والقدرات» ثم تبويب «بيئات التنفيذ» على 1440px. انقد: 1) بنية الدرج: عرضه، عتمته، عزله البصري 2) بطاقات القدرات/المزودين: هل هي نظام مصمم أم HTML خام؟ 3) حالة «القدرات» (READY/NOT_READY) ولونها الدلالي 4) الاتساق مع بقية الواجهة 5) الازدحام والحشو 6) درجة /10 لكل تبويب وأخطر 3 عيوب." -i "./08-settings-tools-1440.png" -i "./09-settings-execution-1440.png" -o vlm-08-09-settings.json 2>&1 | tail -1

z-ai vision -p "$PERSONA هاتان لقطتان لصفحة مشروع حي (مشروع OSINT يعمل فعلاً): التبويب الرئيسي ثم تبويب سير العمل على 1440px. انقد: 1) بطاقة المشروع وحالتها (RUNNING) 2) تتبع المراحل/الخطوات: هل التقدم مفهوم بصرياً؟ 3) بطاقات الاعتمادات/البوابات 4) كثافة المعلومات التقنية مقابل الوضوح 5) الطباعة العربية داخل المكونات التقنية 6) درجة /10 وأخطر 3 عيوب حرفية." -i "./10-project1-1440.png" -i "./12-project1-workflow-1440.png" -o vlm-10-12-project.json 2>&1 | tail -1

z-ai vision -p "$PERSONA هذه 3 لقطات موبايل 390px: الترحيب، المحادثة، صفحة المشروع الحي. انقد تجربة الموبايل: 1) الاستجابة والتخطيط 2) الشريط الجانبي المطوي والتنقل 3) صندوق الإدخال على اللمس 4) بطاقات المشروع والجداول في عرض ضيق 5) أحجام أهداف اللمس 6) درجة /10 وأخطر 3 عيوب للموبايل تحديداً." -i "./14-welcome-390.png" -i "./15-conversation-390.png" -i "./16-project1-390.png" -o vlm-14-16-mobile.json 2>&1 | tail -1

echo "ALL VLM CRITIQUES DONE"
ls -la vlm-*.json
